query.query:
mutation deleteAlbum {
  deleteAlbum {
    queryType {
      fields {
        name
      }
    }
  }
}

mutation deleteAlbum {
  deleteAlbum(id: "<img src='x' onerror='alert(1)'>") {
    Boolean
  }
}

mutation deleteAlbum {
  deleteAlbum(id: "aliasedFieldName") {
    Boolean
  }
  s: deleteAlbum(id: "aliasedFieldName") {
    Boolean
  }
}

mutation deleteAlbumQuery {
  deleteAlbum(id: 1) {
    ... on Error {
      message
    }
  }
}

query Introspection {
  deleteAlbum {
    types {
      name
      kind
    }
  }
}

query FieldSuggestions {
  deleteAlbum(id: "123") {
    __typename
    ... on Node {
      id
    }
  }
}

query {
  deleteAlbum {
    __type(name: "Query") {
      fields {
        name
        type {
          name
        }
      }
    }
  }
}
